// Build prompt context: titles of last 10 published posts + every topic in the calendar
// (regardless of status — we don't want to suggest something that's already Queued/Skipped/etc).
const config = $('Config').first().json;
const githubFiles = $('List Published Posts').first().json || [];
const calendarResp = $('Get Calendar State').first().json || {};

// Posts: filenames look like 2026-04-22-some-slug.md → strip date + extension to get slug
const posts = (Array.isArray(githubFiles) ? githubFiles : [])
  .filter(f => f.name && f.name.endsWith('.md'))
  .sort((a, b) => b.name.localeCompare(a.name)) // newest first by filename date prefix
  .slice(0, 10)
  .map(f => f.name.replace(/^\d{4}-\d{2}-\d{2}-/, '').replace(/\.md$/, '').replace(/-/g, ' '));

// Calendar topics across all statuses — extract title text
function text(prop) {
  if (!prop) return '';
  const arr = prop.title || prop.rich_text || [];
  return arr.map(t => t.plain_text).join('').trim();
}
const calendarTopics = (calendarResp.results || [])
  .map(p => text(p.properties?.Topic || p.properties?.Name || p.properties?.Title))
  .filter(t => t);

return [{ json: {
  ...config,
  publishedSlugs: posts,
  existingCalendarTopics: calendarTopics,
  publishedCount: posts.length,
  calendarCount: calendarTopics.length,
}}];

// Parse the JSON array out of Claude's response. Defensive: model sometimes wraps in code fences
// or adds preamble despite instructions, so strip those before JSON.parse.
const response = $input.first().json;
const config = $('Config').first().json;

if (!response.content || !response.content[0]?.text) {
  throw new Error('Suggestions response malformed: ' + JSON.stringify(response).substring(0, 300));
}

let text = response.content[0].text.trim();
// Strip code fences if present
text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '');
// Find the first [ and last ] in case there's preamble/postamble
const start = text.indexOf('[');
const end = text.lastIndexOf(']');
if (start === -1 || end === -1) {
  throw new Error('No JSON array found in response. Got: ' + text.substring(0, 300));
}
text = text.substring(start, end + 1);

let suggestions;
try {
  suggestions = JSON.parse(text);
} catch (e) {
  throw new Error(`JSON.parse failed: ${e.message}. Cleaned text: ${text.substring(0, 500)}`);
}

if (!Array.isArray(suggestions) || suggestions.length === 0) {
  throw new Error('Parsed result is not a non-empty array: ' + JSON.stringify(suggestions).substring(0, 300));
}

// Normalize each suggestion + carry config forward so the next node can use it
const validTags = ['revops', 'automation', 'tools', 'comparison', 'guide'];
const validPriorities = ['High', 'Medium', 'Low'];

return suggestions.map(s => ({
  json: {
    ...config,
    topic: String(s.topic || '').trim(),
    keyword: String(s.keyword || '').trim(),
    tag: validTags.includes(s.tag) ? s.tag : 'automation',
    priority: validPriorities.includes(s.priority) ? s.priority : 'Medium',
    notes: String(s.notes || '').trim(),
  }
})).filter(item => item.json.topic);

// Aggregate the created suggestions into a single Slack message.
// Each input item is one Notion page creation response; we want the count + topic titles.
const suggestions = $('Parse Suggestions').all().map(i => i.json);
const config = $('Config').first().json;
const lines = suggestions.map((s, i) => `${i + 1}. *${s.topic}* — ${s.priority} priority, ${s.tag}`).join('\n');
return [{ json: {
  slackWebhookUrl: config.slackWebhookUrl,
  count: suggestions.length,
  summary: lines,
  topicsDatabaseId: config.topicsDatabaseId,
}}];

